import * as THREE from 'three/webgpu';
import {
  color,
  texture,
  uv,
  positionLocal,
  normalLocal,
  float,
  mix,
  smoothstep,
  clamp,
  mx_noise_float,
  mx_noise_vec3,
} from 'three/tsl';
import { createMSDFText } from '@/text';

const TITANIUM_COLOR = '#b8bac0';
const PEDESTAL_COLOR = '#14141a';
const PAPER_COLOR = '#e8ecf2';

function pickText(list, role, fallback) {
  if (!Array.isArray(list)) return fallback;
  const found = list.find(
    (entry) => entry && (entry.role === role || entry.type === role)
  );
  return (found && (found.text ?? found.content)) || fallback;
}

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'pedestal-material-study';
  group.userData.handlers = {};

  // ---- scene placement -------------------------------------------------
  const sp = config.scenePosition || {};
  group.position.set(sp.x ?? 0, sp.y ?? 0, sp.z ?? 0);
  const rotXYZ = sp.rotationXYZ || {};
  group.rotation.set(rotXYZ.x ?? 0, rotXYZ.y ?? 0, rotXYZ.z ?? 0);
  const scaleXYZ = sp.scaleXYZ || {};
  group.scale.set(scaleXYZ.x ?? 1, scaleXYZ.y ?? 1, scaleXYZ.z ?? 1);

  // ---- assets ------------------------------------------------------------
  const imageUrl =
    config.assets?.imageUrl ??
    config.imageUrl ??
    '/prism-assets/chrome/brushed-metal.map.png';
  const roughnessTexture = ctx.textureLoader.load(imageUrl);
  roughnessTexture.wrapS = THREE.RepeatWrapping;
  roughnessTexture.wrapT = THREE.RepeatWrapping;
  roughnessTexture.repeat.set(3, 3);

  // ---- torus-knot material study ----------------------------------------
  const knotGeometry = new THREE.TorusKnotGeometry(0.7, 0.22, 220, 36);
  const knotMaterial = new THREE.MeshPhysicalNodeMaterial({
    color: new THREE.Color(TITANIUM_COLOR),
  });
  knotMaterial.metalness = 0.55;
  knotMaterial.roughness = 0.55;
  knotMaterial.clearcoat = 0.22;
  knotMaterial.clearcoatRoughness = 0.35;
  knotMaterial.anisotropy = 0.9;
  knotMaterial.anisotropyRotation = Math.PI / 2;
  knotMaterial.envMapIntensity = 0.7;

  // roughness map injected multiplicatively, centered near 1.0 so texture
  // value drift never zeroes/inverts the surface (swap-proof).
  const baseRoughness = float(0.55);
  const mapSample = texture(roughnessTexture, uv()).r;
  const centeredMap = mapSample.sub(float(0.9)).mul(float(0.6)).add(float(1.0));
  const valueJitter = mx_noise_float(uv().mul(float(180.0))).mul(float(0.02));
  knotMaterial.roughnessNode = clamp(
    baseRoughness.mul(centeredMap).add(valueJitter),
    float(0.05),
    float(1.0)
  );

  // imperfection pass: procedural scratch-noise normal perturbation
  const scratchNoise = mx_noise_vec3(positionLocal.mul(float(40.0)));
  knotMaterial.normalNode = normalLocal.add(scratchNoise.mul(float(0.15))).normalize();

  const knotMesh = new THREE.Mesh(knotGeometry, knotMaterial);
  knotMesh.position.set(0, 0.4, 0);
  group.add(knotMesh);

  // ---- pedestal with chamfered top edge ----------------------------------
  const pedestalRadius = 1.1;
  const pedestalTopY = -0.35;
  const pedestalHeight = 0.5;
  const pedestalBottomY = pedestalTopY - pedestalHeight;
  const chamfer = 0.03;

  const latheProfile = [
    new THREE.Vector2(0, pedestalBottomY),
    new THREE.Vector2(pedestalRadius, pedestalBottomY),
    new THREE.Vector2(pedestalRadius, pedestalTopY - chamfer),
    new THREE.Vector2(pedestalRadius - chamfer, pedestalTopY),
    new THREE.Vector2(0, pedestalTopY),
  ];
  const pedestalGeometry = new THREE.LatheGeometry(latheProfile, 96);
  const pedestalMaterial = new THREE.MeshPhysicalNodeMaterial({
    color: new THREE.Color(PEDESTAL_COLOR),
  });
  pedestalMaterial.roughness = 0.7;
  pedestalMaterial.metalness = 0.35;
  pedestalMaterial.envMapIntensity = 0.7;
  const pedestalMesh = new THREE.Mesh(pedestalGeometry, pedestalMaterial);
  group.add(pedestalMesh);

  // ---- contact shadow (radial gradient plane) ----------------------------
  const shadowMaxRadius = 1.5;
  const shadowGeometry = new THREE.PlaneGeometry(
    shadowMaxRadius * 2,
    shadowMaxRadius * 2,
    1,
    1
  );
  const shadowMaterial = new THREE.MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });
  const distFromCenter = positionLocal.xy.length();
  shadowMaterial.colorNode = color('#000000');
  shadowMaterial.opacityNode = mix(
    float(0.6),
    float(0.0),
    smoothstep(float(pedestalRadius), float(shadowMaxRadius), distFromCenter)
  );
  const shadowMesh = new THREE.Mesh(shadowGeometry, shadowMaterial);
  shadowMesh.rotation.x = -Math.PI / 2;
  shadowMesh.position.y = -0.36;
  group.add(shadowMesh);

  // ---- backdrop with engineered vertical gradient ------------------------
  const backdropGeometry = new THREE.PlaneGeometry(7, 6, 1, 1);
  const backdropMaterial = new THREE.MeshBasicNodeMaterial();
  const gradT = uv().y;
  const stop0 = color('#0b0b10');
  const stop1 = color('#101017');
  const stop2 = color('#16161d');
  const gradLower = mix(stop0, stop1, smoothstep(float(0.0), float(0.7), gradT));
  backdropMaterial.colorNode = mix(
    gradLower,
    stop2,
    smoothstep(float(0.7), float(1.0), gradT)
  );
  const backdropMesh = new THREE.Mesh(backdropGeometry, backdropMaterial);
  backdropMesh.position.set(0, 0, -3);
  group.add(backdropMesh);

  // ---- studio lighting rig (approximating neutral PMREM IBL) -------------
  const keyLight = new THREE.DirectionalLight(0xffffff, 1.4);
  keyLight.position.set(2.5, 3.2, 2.0);
  const fillLight = new THREE.DirectionalLight(0xcfd6e0, 0.5);
  fillLight.position.set(-2.5, 1.0, 1.5);
  const rimLight = new THREE.PointLight(0xffffff, 0.6, 8);
  rimLight.position.set(-1.0, 1.8, -2.0);
  const ambientLight = new THREE.AmbientLight(0xffffff, 0.25);
  group.add(keyLight, fillLight, rimLight, ambientLight);

  // ---- text content (MSDF only) ------------------------------------------
  const headlineText = pickText(
    config.textContent,
    'headline',
    'Material study 03'
  );
  const captionText = pickText(
    config.textContent,
    'caption',
    'GRADE 5 TITANIUM / BRUSHED AT 1200 GRIT'
  );

  const headlineMesh = createMSDFText({
    fontAtlas: ctx.fontAtlas,
    text: headlineText,
    font: 'Lora',
    weight: 600,
    size: 0.34,
    color: PAPER_COLOR,
    letterSpacing: -0.005,
    lineHeight: 1.1,
    anchor: 'center',
  });
  headlineMesh.position.set(0, -1.2, 0.02);
  group.add(headlineMesh);

  const captionMesh = createMSDFText({
    fontAtlas: ctx.fontAtlas,
    text: captionText,
    font: 'JetBrains Mono',
    weight: 400,
    size: 0.09,
    color: PAPER_COLOR,
    letterSpacing: 0.08,
    lineHeight: 1.4,
    anchor: 'center',
  });
  captionMesh.position.set(0, -1.6, 0.02);
  group.add(captionMesh);

  // ---- cinematic primitives ----------------------------------------------
  const primitiveDisposers = [];
  const primitiveRefs = Array.isArray(config.cinematicPrimitives)
    ? config.cinematicPrimitives
    : [];
  for (const primitive of primitiveRefs) {
    const applyPrimitive = ctx.primitives && ctx.primitives[primitive.name];
    if (typeof applyPrimitive !== 'function') continue;
    const target = primitive.name === 'orbit' ? knotMesh : group;
    const disposer = applyPrimitive(target, primitive.params || {});
    if (typeof disposer === 'function') primitiveDisposers.push(disposer);
  }

  // ---- cleanup -------------------------------------------------------------
  group.userData.cleanup = function cleanup() {
    for (const dispose of primitiveDisposers) {
      try {
        dispose();
      } catch (e) {
        // primitive already torn down
      }
    }

    knotGeometry.dispose();
    knotMaterial.dispose();
    pedestalGeometry.dispose();
    pedestalMaterial.dispose();
    shadowGeometry.dispose();
    shadowMaterial.dispose();
    backdropGeometry.dispose();
    backdropMaterial.dispose();
    roughnessTexture.dispose();

    for (const mesh of [headlineMesh, captionMesh]) {
      if (!mesh) continue;
      if (typeof mesh.dispose === 'function') mesh.dispose();
      if (mesh.geometry && typeof mesh.geometry.dispose === 'function') {
        mesh.geometry.dispose();
      }
      if (Array.isArray(mesh.material)) {
        mesh.material.forEach((m) => m && m.dispose && m.dispose());
      } else if (mesh.material && typeof mesh.material.dispose === 'function') {
        mesh.material.dispose();
      }
    }

    group.clear();
  };

  return group;
}
